from pathlib import Path

# Audio manifest: add synth-only pouch-grab cue. Keep it out of AVAILABLE_SFX_CUES.
p = Path('src/game/data/audioAssets.ts')
s = p.read_text()
s = s.replace("  'pouch-select',\n  'ui-denied',", "  'pouch-select',\n  'pouch-grab',\n  'ui-denied',", 1)
s = s.replace("  'pouch-select': 'assets/audio/pouch-select.mp3',\n  'ui-denied':", "  'pouch-select': 'assets/audio/pouch-select.mp3',\n  'pouch-grab': 'assets/audio/pouch-grab.mp3',\n  'ui-denied':", 1)
p.write_text(s)

# Audio controller: material-ish short zip/pop using the existing deterministic noise buffer.
p = Path('src/game/systems/audio.ts')
s = p.read_text()
s = s.replace("  'pouch-select': [\n    { frequency: 520, endFrequency: 720, duration: 0.055, type: 'triangle', gain: 0.026 },\n    { frequency: 920, endFrequency: 1080, duration: 0.045, type: 'sine', gain: 0.018, delay: 0.035 },\n  ],\n  'ui-denied':", "  'pouch-select': [\n    { frequency: 520, endFrequency: 720, duration: 0.055, type: 'triangle', gain: 0.026 },\n    { frequency: 920, endFrequency: 1080, duration: 0.045, type: 'sine', gain: 0.018, delay: 0.035 },\n  ],\n  // `pouch-grab` is generated by schedulePouchGrab for a short plastic zip/pop transient.\n  'pouch-grab': [],\n  'ui-denied':", 1)
s = s.replace("    if (cue === 'chip-clack') {\n      this.scheduleChipClack(context);\n      return;\n    }\n\n    const now", "    if (cue === 'chip-clack') {\n      this.scheduleChipClack(context);\n      return;\n    }\n    if (cue === 'pouch-grab') {\n      this.schedulePouchGrab(context);\n      return;\n    }\n\n    const now", 1)
needle = "  private scheduleChipClack(context: AudioContext): void {\n"
insert = """  private schedulePouchGrab(context: AudioContext): void {
    const now = context.currentTime;
    const noise = context.createBufferSource();
    noise.buffer = this.getChipNoiseBuffer(context);
    const band = context.createBiquadFilter();
    band.type = 'bandpass';
    band.frequency.setValueAtTime(3300, now);
    band.Q.setValueAtTime(1.35, now);
    const noiseGain = context.createGain();
    noiseGain.gain.setValueAtTime(0.0001, now);
    noiseGain.gain.exponentialRampToValueAtTime(0.043, now + 0.001);
    noiseGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.027);
    noise.connect(band);
    band.connect(noiseGain);
    noiseGain.connect(context.destination);
    noise.start(now);
    noise.stop(now + 0.032);

    const body = context.createOscillator();
    const bodyGain = context.createGain();
    body.type = 'triangle';
    body.frequency.setValueAtTime(430, now + 0.004);
    body.frequency.exponentialRampToValueAtTime(255, now + 0.052);
    bodyGain.gain.setValueAtTime(0.0001, now);
    bodyGain.gain.exponentialRampToValueAtTime(0.028, now + 0.005);
    bodyGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.055);
    body.connect(bodyGain);
    bodyGain.connect(context.destination);
    body.start(now + 0.004);
    body.stop(now + 0.06);
  }

"""
if needle not in s:
    raise SystemExit('audio schedule insertion target missing')
s = s.replace(needle, insert + needle, 1)
p.write_text(s)

